\node[hdr] (lh) at (-3.5, 0){Product Rule};
\node[box, anchor=north]  at (-3.5, -0.45){
    Task 1 \textbf{AND} Task 2\\[5pt]
    $n_1 \times n_2$\\[5pt]
    Tasks are \textbf{independent}\\[5pt]
    Keywords: sequential,\\
    simultaneous, slots\\[5pt]
    \textit{Example: $26^2 \times 10^4$}
};


\node[font=\small\bfseries, text=accentorange] at (0, -2.2){\textbf{vs}};


\node[hdr] (rh) at (3.5, 0){Sum Rule};
\node[box, anchor=north]  at (3.5, -0.45){
    Case 1 \textbf{OR} Case 2\\[5pt]
    $n_1 + n_2$\\[5pt]
    Cases are \textbf{disjoint}\\[5pt]
    Keywords: or, either,\\
    alternative, format\\[5pt]
    \textit{Example: 6.76M + 45.7M}
};
\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 4.1: Product Rule (AND) vs Sum
Rule (OR). Most problems combine both.}}
\end{center}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{\faLightbulb\ Section 4.1 Summary ---
Basic Counting Principles}}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Four Rules:}}
\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Rule} & \textbf{When to use} & \textbf{Formula} \\
\hline
Product & Do task 1 AND task 2 & $n_1 \times n_2$ \\
\hline
Sum & Choose case 1 OR case 2 (disjoint) & $n_1 + n_2$ \\
\hline
Subtraction & Count complement, subtract & $N - n_{\text{bad}}$ \\
\hline
Division & Each object counted $d$ times & total $\div\, d$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Quick Decision Guide:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{``and''} / sequential tasks $\to$ \textbf{multiply}
    \item \textbf{``or''} / separate cases $\to$ \textbf{add}
    \item \textbf{``at least''} / \textbf{``at most''} $\to$
          complement: total $-$ opposite
    \item \textbf{No repetition} $\to$ choices decrease:
          $n,\, n{-}1,\, n{-}2,\ldots$
    \item \textbf{With repetition} $\to$ choices constant: $n^k$
\end{itemize}

\vspace{0.4cm}
\textcolor{accentorange}{\textbf{Past Paper Connection:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{2020 Q1(x):} Name the basic counting principles
          $\rightarrow$ Definitions 4.1 \& 4.2
    \item \textbf{2021 Q1(vii):} Edges in a 10-vertex degree-6 graph
          $\rightarrow$ Example 4(a) (division rule)
    \item \textbf{2022 Q1(viii):} $|A|$ where $A$ = odd integers $< 10$
          $\rightarrow$ Example 3(a)
    \item \textbf{2023 Q1(xii):} Car plates, no repetition
          $\rightarrow$ Example 1(a)
    \item \textbf{2025 Q4:} License plates, two formats, sum + product
          $\rightarrow$ Example 2
\end{itemize}

\vspace{0.5cm}

The \textbf{factorial} of a non-negative integer $n$, written $n!$, is:
\[
    n! = n \times (n-1) \times (n-2) \times \cdots \times 2 \times 1
    \qquad \text{with } 0! = 1
\]

\vspace{0.3cm}
\textbf{Common values:}
\begin{center}
\begin{tabular}{|c|c|c|c|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$n$ & 0 & 1 & 2 & 3 & 4 & 5 & 6 \\
\hline
$n!$ & 1 & 1 & 2 & 6 & 24 & 120 & 720 \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key identity:}}
$n! = n \times (n-1)!$ \quad (useful for simplifying expressions)

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} Used throughout 2023 Q3

\vspace{0.5cm}

A \textbf{permutation} is an \textbf{ordered} arrangement of objects.

\vspace{0.4cm}
\textbf{Permutation of $n$ distinct objects taken $r$ at a time:}
\[
    P(n,r) = \frac{n!}{(n-r)!}
    = n \times (n-1) \times \cdots \times (n-r+1)
    \qquad (0 \leq r \leq n)
\]

\textbf{Permutation of all $n$ objects:}
\[
    P(n,n) = n!
\]

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Properties:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Order matters}: arrangement $AB$ is different from $BA$.
    \item Each object can be used \textbf{at most once} (no repetition).
    \item Think of filling $r$ ordered slots: first slot has $n$ choices,
          second has $n-1$, and so on.
\end{itemize}

\vspace{0.4cm}
\textbf{Quick reference:}
\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
Expression & Expanded & Value \\
\hline
$P(5,2)$ & $5 \times 4$ & 20 \\
$P(6,3)$ & $6 \times 5 \times 4$ & 120 \\
$P(7,7)$ & $7!$ & 5040 \\
$P(7,1)$ & $7$ & 7 \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2023 Q3 (all 6 parts use permutation logic),
2023 Q1(xii), 2025 Q4

\vspace{0.5cm}

\textbf{(a)} How many ways can 5 students be arranged in a row?

\textbf{(b)} How many 3-letter arrangements can be made from
MATH (no repetition)?

\textbf{(c)} A president, vice-president, and secretary are chosen from
10 candidates. How many ways?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.2cm}
\textbf{(a)} Arrange all 5 students in order:
\[
    P(5,5) = 5! = \boxed{120}
\]

\textbf{(b)} Choose 3 from 4 letters \{M,A,T,H\}, order matters:
\[
    P(4,3) = \frac{4!}{(4-3)!} = \frac{24}{1} = 4 \times 3 \times 2 = \boxed{24}
\]

\textbf{(c)} Three distinct roles from 10 candidates, order matters:
\[
    P(10,3) = 10 \times 9 \times 8 = \boxed{720}
\]

\vspace{0.5cm}

The number of distinct permutations of $n$ objects where object 1
appears $n_1$ times, object 2 appears $n_2$ times, \ldots, object $k$
appears $n_k$ times (with $n_1 + n_2 + \cdots + n_k = n$) is:
\[
    \frac{n!}{n_1!\; n_2!\; \cdots\; n_k!}
\]

\vspace{0.3cm}
\textbf{Examples:}
\begin{itemize}[leftmargin=1.5em]
    \item Arrangements of \textbf{AABB} (4 letters: A$\times$2, B$\times$2):
          $\dfrac{4!}{2!\,2!} = 6$
    \item Arrangements of \textbf{MISSISSIPPI} (11 letters:
          M$\times$1, I$\times$4, S$\times$4, P$\times$2):
          $\dfrac{11!}{1!\,4!\,4!\,2!} = 34{,}650$
\end{itemize}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2023 Q3 ---
required strings treated as single repeated units.

\vspace{0.5cm}

To count permutations of $n$ objects that \textbf{must contain a
specific consecutive substring}:

\begin{enumerate}[leftmargin=2em]
    \item \textbf{Glue} all letters of the required string into one
          single block.
    \item Count the total objects to arrange: $(n - s + 1)$ where $s$
          is the length of the glued string.
    \item Total permutations $= (n - s + 1)!$
\end{enumerate}

\vspace{0.3cm}
\textbf{Multiple required strings:} Glue each required string into its
own block, then count arrangements of all blocks and remaining letters.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Overlapping strings:}}
If two required strings \textbf{share a letter at the joining point},
merge them into one combined block.
If two strings share a letter but the overlap is \textbf{incompatible}
(the letter must occupy two different positions), the answer is $\mathbf{0}$.

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} 2023 Q3 (all 6 parts)

\vspace{0.5cm}

How many permutations of \textbf{ABCDEFG} ($n=7$ distinct letters)
contain the following strings?

\textbf{i)} BCD \quad
\textbf{ii)} CFGA \quad
\textbf{iii)} BA and GF \quad
\textbf{iv)} ABC and DE \quad
\textbf{v)} ABC and CDE \quad
\textbf{vi)} CBA and BED

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{i) String BCD (length 3):}

Glue $\{B,C,D\}$ into block $[BCD]$. Remaining letters: $A,E,F,G$.
Total objects: $[BCD], A, E, F, G$ $= 5$.
\[
    5! = \boxed{120}
\]

\vspace{0.2cm}
\textbf{ii) String CFGA (length 4):}

Glue $\{C,F,G,A\}$ into block $[CFGA]$. Remaining: $B,D,E$.\\
Total objects: $[CFGA], B, D, E$ $= 4$.
\[
    4! = \boxed{24}
\]

\vspace{0.2cm}
\textbf{iii) Strings BA and GF (two separate blocks):}

Glue $B,A \to [BA]$. Glue $G,F \to [GF]$.
Total objects: $[BA], [GF], C, D, E$ $= 5$.
\[
    5! = \boxed{120}
\]

\vspace{0.2cm}
\textbf{iv) Strings ABC and DE (two non-overlapping blocks):}

Glue $A,B,C \to [ABC]$. Glue $D,E \to [DE]$.
Total objects: $[ABC], [DE], F, G$ $= 4$.
\[
    4! = \boxed{24}
\]

\vspace{0.2cm}
\textbf{v) Strings ABC and CDE (overlapping at C):}

ABC ends in C; CDE starts with C. For both substrings to appear,
C must be simultaneously the 3rd letter of ABC and the 1st letter
of CDE, forcing the combined block $[ABCDE]$.
Total objects: $[ABCDE], F, G$ $= 3$.
\[
    3! = \boxed{6}
\]

\vspace{0.2cm}
\textbf{vi) Strings CBA and BED (B appears in both):}

CBA contains B at position 2; BED starts with B.
Since B is a single letter appearing once in ABCDEFG, it cannot
simultaneously be in two different positions required by CBA and BED.
\[
    \text{Answer} = \boxed{0}
\]

\vspace{0.5cm}

A \textbf{combination} is an \textbf{unordered} selection of objects.

\vspace{0.4cm}
\textbf{Number of ways to choose $r$ objects from $n$ distinct objects
(order does not matter):}
\[
    C(n,r) = \binom{n}{r} = \frac{n!}{r!\,(n-r)!}
    \qquad (0 \leq r \leq n)
\]

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Properties:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Order does not matter}: $\{A,B\} = \{B,A\}$.
    \item $\binom{n}{r} = \binom{n}{n-r}$ \quad (symmetry)
    \item $\binom{n}{0} = \binom{n}{n} = 1$; \quad $\binom{n}{1} = n$
    \item \textbf{Link to permutation:} $P(n,r) = \binom{n}{r} \times r!$
\end{itemize}

\vspace{0.4cm}
\textbf{Quick reference:}
\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
Expression & Expanded & Value \\
\hline
$\binom{5}{2}$ & $\dfrac{5\times4}{2!}$ & 10 \\[4pt]
$\binom{6}{3}$ & $\dfrac{6\times5\times4}{3!}$ & 20 \\[4pt]
$\binom{7}{4}$ & $\dfrac{7\times6\times5\times4}{4!}$ & 35 \\[4pt]
$\binom{10}{5}$ & $\dfrac{10!}{5!\,5!}$ & 252 \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Past Paper:}} Selection / committee
problems appear in exam-style 4.2 questions.

\vspace{0.5cm}

\textbf{(a)} How many ways can a committee of 3 be chosen from 10 people?

\textbf{(b)} A class has 12 boys and 8 girls. How many committees of 5
contain exactly 3 boys and 2 girls?

\textbf{(c)} How many ways can you choose at least one book from a
shelf of 4 different books?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.2cm}
\textbf{(a)} Order does not matter (committee):
\[
    \binom{10}{3} = \frac{10 \times 9 \times 8}{3!} = \frac{720}{6} = \boxed{120}
\]

\textbf{(b)} Choose boys AND choose girls (product rule with combinations):
\[
    \binom{12}{3} \times \binom{8}{2}
    = \frac{12 \times 11 \times 10}{6} \times \frac{8 \times 7}{2}
    = 220 \times 28 = \boxed{6{,}160}
\]

\textbf{(c)} Each book independently chosen or not $\Rightarrow 2^4$ total subsets.
At least one book = total $-$ empty set:
\[
    2^4 - 1 = 16 - 1 = \boxed{15}
\]

\vspace{0.5cm}

\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Feature} & \textbf{Permutation} & \textbf{Combination} \\
\hline
Order & Matters ($AB \neq BA$) & Does not matter ($AB = BA$) \\
\hline
Formula & $\dfrac{n!}{(n-r)!}$ & $\dfrac{n!}{r!\,(n-r)!}$ \\
\hline
Keywords & arrange, rank, seat, & choose, select, committee, \\
         & schedule, order & group, team, subset \\
\hline
Example & Top-3 finishers in race & 3 members from a club \\
\hline
Relation & \multicolumn{2}{c|}{$P(n,r) = C(n,r) \times r!$} \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Quick test:}}
Ask \textit{``Does swapping two chosen items give a different result?''}
Yes $\to$ Permutation. \quad No $\to$ Combination.

\vspace{0.5cm}

Identify whether each uses P or C, then solve.

\textbf{(a)} 8 runners compete; how many ways can gold, silver, and
bronze medals be awarded?

\textbf{(b)} A team of 4 is chosen from 9 players. How many teams?

\textbf{(c)} How many 4-digit PIN codes use digits 0--9 with no
repeated digit?

\textbf{(d)} From 5 men and 4 women, how many committees of 4
contain \textbf{at least 2 women}?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.2cm}
\textbf{(a)} Different medals $\Rightarrow$ order matters.
\textbf{Permutation.}
\[
    P(8,3) = 8 \times 7 \times 6 = \boxed{336}
\]

\textbf{(b)} Team membership, no roles $\Rightarrow$ order does not matter.
\textbf{Combination.}
\[
    \binom{9}{4} = \frac{9 \times 8 \times 7 \times 6}{4!} = \boxed{126}
\]

\textbf{(c)} 4 ordered positions, no repetition.
\textbf{Permutation.}
\[
    P(10,4) = 10 \times 9 \times 8 \times 7 = \boxed{5040}
\]

\textbf{(d)} At least 2 women: split into cases.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
Women & Men & Ways & Count \\
\hline
2 & 2 & $\binom{4}{2}\times\binom{5}{2}$ & $6\times10=60$ \\
3 & 1 & $\binom{4}{3}\times\binom{5}{1}$ & $4\times5=20$ \\
4 & 0 & $\binom{4}{4}\times\binom{5}{0}$ & $1\times1=1$ \\
\hline
\multicolumn{3}{|r|}{Total} & $\mathbf{81}$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.5cm}

\textbf{(a) [2023 Q1(xii)]} A car plate: 4 digits from $\{1,\ldots,9\}$
then 3 letters from 26, no repetition within each group.

\textbf{(b) [2025 Q4]} License plates: 2 letters + 4 digits OR
2 digits + 4 letters, repetition allowed.

\textbf{(c)} Compare: choose 3 letters for a code where order
matters vs order does not matter.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.2cm}
\textbf{(a)} Different positions are distinct, no repetition.
This is a \textbf{permutation} calculation.

Digits in order: $P(9,4) = 9 \times 8 \times 7 \times 6 = 3024$

Letters in order: $P(26,3) = 26 \times 25 \times 24 = 15{,}600$

Total (product rule):
\[
    3024 \times 15{,}600 = \boxed{47{,}174{,}400}
\]

\vspace{0.2cm}
\textbf{(b)} Repetition allowed $\Rightarrow$ not a pure permutation;
use product rule with independent slots.

Case 1 (2L + 4D): $26^2 \times 10^4 = 676 \times 10{,}000 = 6{,}760{,}000$

Case 2 (2D + 4L): $10^2 \times 26^4 = 100 \times 456{,}976 = 45{,}697{,}600$

By sum rule (disjoint formats):
\[
    6{,}760{,}000 + 45{,}697{,}600 = \boxed{52{,}457{,}600}
\]

\vspace{0.2cm}
\textbf{(c)} Choose 3 from 26 letters:

Order matters (permutation):
$P(26,3) = 26 \times 25 \times 24 = 15{,}600$

Order does not matter (combination):
$\binom{26}{3} = \dfrac{15{,}600}{3!} = \dfrac{15{,}600}{6} = 2{,}600$

The permutation is exactly $3! = 6$ times the combination,
since each set of 3 letters can be ordered in $3!$ ways.

\vspace{0.5cm}




