\node[hdr] at (-3.5, 0){Permutation $P(n,r)$};
\node[box, anchor=north] at (-3.5, -0.45){
    \textbf{Order matters}\\[5pt]
    $AB \neq BA$\\[6pt]
    $\dfrac{n!}{(n-r)!}$\\[8pt]
    Keywords: arrange, rank,\\
    schedule, seat, order\\[5pt]
    \textit{Medals, PIN codes,}\\
    \textit{ordered plates}
};

\node[font=\small\bfseries, text=accentorange] at (0, -2.5){\textbf{vs}};

\node[hdr] at (3.5, 0){Combination $\binom{n}{r}$};
\node[box, anchor=north] at (3.5, -0.45){
    \textbf{Order does not matter}\\[5pt]
    $AB = BA$\\[6pt]
    $\dfrac{n!}{r!\,(n-r)!}$\\[8pt]
    Keywords: choose, select,\\
    committee, group, team\\[5pt]
    \textit{Committees,}\\
    \textit{card hands, subsets}
};
\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 4.2: Permutation (order matters)
vs Combination (order does not matter).
Relation: $P(n,r) = C(n,r) \times r!$}}
\end{center}

\vspace{0.5cm}

