\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Key Summation Formulas:}}
\[
    \sum_{j=1}^{n}j = \frac{n(n+1)}{2}
    \qquad
    \sum_{j=1}^{n}j^2 = \frac{n(n+1)(2n+1)}{6}
    \qquad
    \sum_{j=0}^{n}r^j = \frac{r^{n+1}-1}{r-1}
\]

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Recursive Algorithm:}}
\begin{itemize}[leftmargin=1.5em]
    \item Base case: handle simplest input directly.
    \item Recursive case: reduce and call self on smaller input.
    \item Trace by following descent (print before call) then ascent
          (print after call returns).
\end{itemize}

